/**
 * Cloudberry substrate — items, document facts, rule emission and the region payload.
 *
 * A Cloudberry region is one Cloudberry Kingdom level, generated by the game's own
 * generator (the Cloudberry repo, `ck-level/2`) and replayed by the game page from
 * the same request. Nothing here simulates the game: the rules come from the
 * generated DOCUMENT's facts (the Cloudberry plan's "How P2 makes a payload"):
 *
 *   - a level is nested pieces; piece k is generated with the platform items
 *     S_k = items(piece 0) ∪ … ∪ items(piece k) (S_1 ⊆ S_2 ⊆ …), each piece's new
 *     items verified real by the generator's reroll search (⚖ R14);
 *   - a CHECK COIN in piece k needs S_k; the END DOOR (every exit) needs S_last;
 *   - a level generated with the Jetpack hero (`level.heroAbility.JetPack`) needs
 *     `Jetpack` everywhere (⚖ R15).
 *
 * These are SUFFICIENT sets (what the computer's recording used), not minimal:
 * the safe direction — the logic never claims a coin the player cannot reach.
 *
 * Emission is in the shared paths-and-obstacles vocabulary (runner's pattern,
 * `runnerDemo/apRules.js`): one physics obstacle per game item,
 * `cloudberry_gate_<GameItem>`, cleared by its AP item; authored terms the level
 * cannot realise (foreign items, counts above 1) become per-term `logic_gate`
 * obstacles ANDed onto every path, and ride the payload as `gate_rules` for the
 * flash bridge to evaluate at run time.
 *
 * Pure: no DOM, no fetch — unit tested by `cloudberryRules.test.js`, imported by
 * the registry entry, the pack maker and the CLI checks.
 */

import { makeAndRule, makeHasRule } from '../shared/rulesJsonBuilder.js';

/** The payload version the Cloudberry game page reads (`embed.js` PAYLOAD_VERSION). */
export const CLOUDBERRY_PAYLOAD_VERSION = 'cloudberry-region/1';
/** The game id every Cloudberry payload carries. */
export const CLOUDBERRY_GAME_ID = 'cloudberry';

/**
 * The ten game items (⚖ R3/R8: the nine platform types, FlyBlob included; ⚖ R15:
 * Jetpack) → their AP item names. Order is the emission order of obstacles on a path.
 */
export const CLOUDBERRY_ITEM_NAMES = Object.freeze({
    MovingBlock: 'Moving Blocks',
    FallingBlock: 'Falling Blocks',
    BouncyBlock: 'Bouncy Blocks',
    GhostBlock: 'Ghost Blocks',
    Cloud: 'Clouds',
    Elevator: 'Elevators',
    Pendulum: 'Pendulums',
    Conveyor: 'Conveyors',
    FlyBlob: 'Fly Blobs',
    Jetpack: 'Jetpack',
});
export const CLOUDBERRY_GAME_ITEMS = Object.freeze(Object.keys(CLOUDBERRY_ITEM_NAMES));
/** AP item name → game item (the payload's `items` map; the page's pollItems reads it). */
export const CLOUDBERRY_ITEMS_BY_AP_NAME = Object.freeze(Object.fromEntries(
    Object.entries(CLOUDBERRY_ITEM_NAMES).map(([game, ap]) => [ap, game])));
export const CLOUDBERRY_VICTORY_ITEM = 'Victory';

/** Archipelago-CC grid sides → the game page's side names (its exit menu and bot portals). */
export const PAGE_SIDE = Object.freeze({ N: 'north', E: 'east', S: 'south', W: 'west' });
export const GRID_SIDE = Object.freeze(Object.fromEntries(Object.entries(PAGE_SIDE).map(([g, p]) => [p, g])));

export const obstacleIdFor = (gameItem) => `cloudberry_gate_${gameItem}`;

/** Registry-declared item library: the ten items + Victory (panel colours; ids = AP names). */
export const CLOUDBERRY_LIBRARY_ITEMS = Object.freeze(Object.fromEntries([
    ['MovingBlock', '#4f8fd6'], ['FallingBlock', '#c9773b'], ['BouncyBlock', '#5cc25c'],
    ['GhostBlock', '#a0a0c8'], ['Cloud', '#d8e8f8'], ['Elevator', '#8a7bd0'],
    ['Pendulum', '#c4a24a'], ['Conveyor', '#6d6d6d'], ['FlyBlob', '#d0608f'], ['Jetpack', '#e04b2a'],
].map(([game, color]) => {
    const name = CLOUDBERRY_ITEM_NAMES[game];
    return [name, { id: name, name, classification: 'progression', color, symbol: 'star', feature: 'cloudberry_items' }];
}).concat([[CLOUDBERRY_VICTORY_ITEM, {
    id: CLOUDBERRY_VICTORY_ITEM, name: CLOUDBERRY_VICTORY_ITEM, classification: 'progression',
    color: '#f5d020', symbol: 'star', feature: 'cloudberry_items', is_victory: true,
}]])));

/** The physics obstacle library: one per game item, cleared by its AP item. */
export const CLOUDBERRY_LIBRARY_OBSTACLES = Object.freeze(Object.fromEntries(
    CLOUDBERRY_GAME_ITEMS.map((game) => {
        const id = obstacleIdFor(game);
        const name = CLOUDBERRY_ITEM_NAMES[game];
        return [id, {
            id,
            name: game === 'Jetpack' ? 'Jetpack Level' : `${name} Section`,
            clear_set_type: 'combo_list',
            clear_set: [[name]],
            color: CLOUDBERRY_LIBRARY_ITEMS[name].color,
            feature: 'cloudberry_items',
            cloudberry_item: game,
        }];
    })));

const sortGameItems = (items) => [...new Set(items)]
    .sort((a, b) => CLOUDBERRY_GAME_ITEMS.indexOf(a) - CLOUDBERRY_GAME_ITEMS.indexOf(b));

function assertGameItems(items, where) {
    for (const it of items) {
        if (!CLOUDBERRY_ITEM_NAMES[it]) throw new Error(`${where}: unknown Cloudberry item '${it}'`);
    }
}

/**
 * The rule-relevant FACTS of a generated document:
 *   { pieceItems: [[game items of piece 0], …], jetpack: bool,
 *     coins: [{ id, piece, tick }] }   — only WITNESSED coins (the computer collects them)
 * `doc` is the parsed `ck-level/2` document. Refuses a document with an error.
 */
export function documentFacts(doc) {
    if (!doc || typeof doc !== 'object') throw new Error('documentFacts: no document');
    if (doc.error) throw new Error(`documentFacts: the generator refused: ${doc.error}`);
    const pieces = (doc.seedPieces ?? []).filter((p) => p.kind === 'piece')
        .sort((a, b) => a.piece - b.piece);
    if (pieces.length === 0) throw new Error('documentFacts: the document has no pieces');
    const pieceItems = pieces.map((p, k) => {
        if (p.piece !== k) throw new Error(`documentFacts: piece ${k} missing (found ${p.piece})`);
        const items = (p.items ?? []).filter((it) => it !== 'NormalBlock');
        assertGameItems(items, `documentFacts: piece ${k}`);
        return sortGameItems(items);
    });
    const coins = (doc.coins?.list ?? []).filter((c) => c.witness)
        .map((c) => ({ id: c.id, piece: c.piece, tick: c.witness.tick }));
    return { pieceItems, jetpack: doc.level?.heroAbility?.JetPack === true, coins };
}

/**
 * Choose the check coins (⚖ R19): `perPiece` per piece, among that piece's WITNESSED
 * coins, spread evenly through the piece by witness tick (one coin → the middle one,
 * host-sim's choice). Returns [{ name: 'coin<id>', coin, piece }] in piece order.
 */
export function chooseCheckCoins(facts, perPiece = 1) {
    const out = [];
    for (let k = 0; k < facts.pieceItems.length; k++) {
        const list = facts.coins.filter((c) => c.piece === k).sort((a, b) => a.tick - b.tick || a.id - b.id);
        const n = Math.min(perPiece, list.length);
        for (let i = 0; i < n; i++) {
            const c = list[Math.floor(((i + 0.5) * list.length) / n)];
            out.push({ name: `coin${c.id}`, coin: c.id, piece: k });
        }
    }
    return out;
}

/** S_k as game items: the union of pieces 0..k, + Jetpack for a Jetpack level. */
export function requiredItems(facts, piece) {
    if (piece < 0 || piece >= facts.pieceItems.length) {
        throw new Error(`requiredItems: piece ${piece} out of range (${facts.pieceItems.length} pieces)`);
    }
    const set = facts.pieceItems.slice(0, piece + 1).flat();
    if (facts.jetpack) set.push('Jetpack');
    return sortGameItems(set);
}

/** S_last: what the end door (every exit) needs. */
export const exitItems = (facts) => requiredItems(facts, facts.pieceItems.length - 1);

function authoredObstacleId({ item, count }) {
    const slug = String(item).replace(/[^A-Za-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    return (count ?? 1) > 1 ? `cloudberry_logic_${slug}__x${count}` : `cloudberry_logic_${slug}`;
}

/**
 * A goal's access as paths: ONE path (the requirement is a single sufficient set)
 * holding a physics obstacle per game item, then a `logic_gate` obstacle per
 * authored term. Empty → one empty path (always open).
 * @returns {{ paths, authoredDefs }}
 */
export function emitCloudberryPaths(gameItems, authoredTerms = []) {
    assertGameItems(gameItems, 'emitCloudberryPaths');
    const authoredDefs = {};
    const authoredIds = (authoredTerms ?? []).map((term) => {
        const id = authoredObstacleId(term);
        const count = term.count ?? 1;
        authoredDefs[id] = {
            id,
            name: `${term.item}${count > 1 ? ` x${count}` : ''} Gate`,
            clear_set_type: 'rule',
            clear_rule: makeHasRule(term.item, count),
            feature: 'cloudberry_items',
        };
        return id;
    });
    return {
        paths: [{ path_id: 'p1', obstacles: [...sortGameItems(gameItems).map(obstacleIdFor), ...authoredIds] }],
        authoredDefs,
    };
}

/** The same requirement as one Rule Builder rule (the legacy form; tests compare the two). */
export function requirementRule(gameItems, authoredTerms = []) {
    return makeAndRule([
        ...sortGameItems(gameItems).map((g) => makeHasRule(CLOUDBERRY_ITEM_NAMES[g])),
        ...(authoredTerms ?? []).map(({ item, count }) => makeHasRule(item, count ?? 1)),
    ]);
}

/**
 * Emit a region's rules from its facts and chosen checks:
 *   { locations: [{id, item, paths, position}], exitPaths: {side: paths}, obstacleDefs,
 *     gateRules: {portals, pickups} }
 * `checks` = chooseCheckCoins output; `items` = { checkName: AP item | null };
 * `exitSides` = grid sides; `authored` = { exits: {side: terms}, locations: {name: terms} }.
 * gate_rules portals are keyed by the PAGE side (the page's gates are by side).
 */
export function emitCloudberryRules(facts, { checks, items = {}, exitSides = [], authored = {} } = {}) {
    const obstacleDefs = {};
    const referenced = new Set();
    const gateRules = { portals: {}, pickups: {} };
    const take = ({ paths, authoredDefs }) => {
        Object.assign(obstacleDefs, authoredDefs);
        for (const o of paths[0].obstacles) if (CLOUDBERRY_LIBRARY_OBSTACLES[o]) referenced.add(o);
        return paths;
    };
    const locations = (checks ?? []).map((c) => {
        const terms = authored.locations?.[c.name] ?? [];
        if (terms.length) gateRules.pickups[c.name] = requirementRule([], terms);
        return {
            id: c.name,
            item: items[c.name] ?? null,
            paths: take(emitCloudberryPaths(requiredItems(facts, c.piece), terms)),
            position: null,
        };
    });
    const exitPaths = {};
    const last = exitItems(facts);
    for (const side of exitSides) {
        if (!PAGE_SIDE[side]) throw new Error(`emitCloudberryRules: unknown side '${side}'`);
        const terms = authored.exits?.[side] ?? [];
        if (terms.length) gateRules.portals[PAGE_SIDE[side]] = requirementRule([], terms);
        exitPaths[side] = take(emitCloudberryPaths(last, terms));
    }
    for (const id of [...referenced].sort()) obstacleDefs[id] = CLOUDBERRY_LIBRARY_OBSTACLES[id];
    return { locations, exitPaths, obstacleDefs, gateRules };
}

/**
 * The region payload the registry entry stores (`playable_payload`). `params` is the
 * Cloudberry page's region payload minus what is derived at load time from the world
 * (the exits, the side portals, entrySide — see the entry's deserializeWorld).
 *
 * @param {string} region_id
 * @param {object} region  { generate, docSha256, checks: [{name, coin}], gateRules? }
 */
export function buildCloudberryPayload(region_id, { generate, docSha256, checks, gateRules = null }) {
    if (!generate || typeof generate !== 'object') throw new Error('buildCloudberryPayload: no generate request');
    if (generate.reroll !== undefined) throw new Error('buildCloudberryPayload: a reroll search, not the resolved request');
    if (!/^[0-9a-f]{64}$/.test(docSha256 ?? '')) throw new Error('buildCloudberryPayload: docSha256 is not 64 hex');
    const payload = {
        gameId: CLOUDBERRY_GAME_ID,
        params: {
            payload: CLOUDBERRY_PAYLOAD_VERSION,
            generate,
            docSha256,
            checks: Object.fromEntries(checks.map((c) => [c.name, c.coin])),
            items: { ...CLOUDBERRY_ITEMS_BY_AP_NAME },
        },
        ap_locations: Object.fromEntries(checks.map((c) => [c.name, `${region_id}__${c.name}`])),
        flashCapabilities: { locations: 'cooperative', items: 'pull', start: 'auto' },
    };
    if (gateRules && (Object.keys(gateRules.portals ?? {}).length || Object.keys(gateRules.pickups ?? {}).length)) {
        payload.gate_rules = gateRules;
    }
    return payload;
}

/**
 * Load-time translation of a Cloudberry world into the page's vocabulary (the entry's
 * deserializeWorld runs it on the flash-deserialized world, whose `exits` is a Map):
 *   params.exits       ← the world's exits [{side: page side, exitName}] (the bridge
 *                        resolves the page's sendExit(exitName, side) by exitName)
 *   params.sidePortals ← {grid side: page side} (the bridge's walkTo: portal id = side)
 *   params.entrySide   ← params.backExitSide as a page side (the start door's way back), else null
 */
export function pageParamsForWorld(world) {
    const params = { ...(world.params ?? {}) };
    const exits = world.exits instanceof Map ? [...world.exits.values()]
        : (Array.isArray(world.exits) ? world.exits : []);
    params.exits = exits.filter((e) => PAGE_SIDE[e?.side]).map((e) => ({
        side: PAGE_SIDE[e.side],
        exitName: e.exitName ?? e.exit_id,
        ...(typeof e.label === 'string' ? { label: e.label } : {}),
    }));
    params.sidePortals = { ...PAGE_SIDE };
    params.entrySide = PAGE_SIDE[params.backExitSide] ?? null;
    return params;
}
